}
E
mkdir -p tests/CheckoutPricing.UnitTests/Acceptance && cat > tests/CheckoutPricing.UnitTests/Acceptance/LoyaltyDiscountTests.cs <<'E'
using CheckoutPricing.Application;

namespace CheckoutPricing.UnitTests.Acceptance;

public sealed class LoyaltyDiscountTests
{
    [Fact]
    public void Gold_customer_receives_the_approved_discount()
    {
        var checkout = new Checkout();

        var payable = checkout.CalculatePayableTotal(CustomerTier.Gold, 100.00m);

        Assert.Equal(95.00m, payable);
    }
}
